(()=>{
 const root=document.getElementById('telepat-v7-clean');
 const feed=document.querySelector('[data-telepat-native] [role="feed"]');
 if(!root||!feed)return;
 const oldPadding=feed.style.getPropertyValue('padding-bottom'),oldPriority=feed.style.getPropertyPriority('padding-bottom');
 let follow=true,lastNode=null,frame=0,closed=false;
 function latest(){const a=feed.querySelectorAll('[role="article"],article');return a[a.length-1]||null;}
 function align(){frame=0;if(closed)return;const last=latest();if(!last)return;if(last!==lastNode)lastNode=last;if(!follow){clamp();return;}
 const h=last.getBoundingClientRect().height;feed.style.setProperty('padding-bottom',Math.max(12,feed.clientHeight-h-12)+'px','important');
 const a=last.getBoundingClientRect(),b=feed.getBoundingClientRect();const target=feed.scrollTop+a.top-b.top-12;
 if(Math.abs(feed.scrollTop-target)>1)feed.scrollTop=target;
 }
 function schedule(){if(!frame&&!closed)frame=requestAnimationFrame(align);}
 function wheel(e){if(e.deltaY!==0)follow=false;}
 function key(e){if(['PageUp','PageDown','Home','End','ArrowUp','ArrowDown',' '].includes(e.key))follow=false;}
 function pointer(e){const r=feed.getBoundingClientRect();if(e.clientX>=r.right-18)follow=false;}
 function bottomLimit(){const last=latest();if(!last)return 0;const a=last.getBoundingClientRect(),b=feed.getBoundingClientRect();const start=feed.scrollTop+a.top-b.top;return Math.max(0,start-12,start+a.height-feed.clientHeight+12);}
 function clamp(){const limit=bottomLimit();if(feed.scrollTop>limit+1)feed.scrollTop=limit;}
 function scroll(){clamp();}
 const observer=new MutationObserver(schedule);observer.observe(feed,{childList:true,subtree:true,characterData:true});
 feed.addEventListener('wheel',wheel,{passive:true});feed.addEventListener('keydown',key);feed.addEventListener('pointerdown',pointer);feed.addEventListener('scroll',scroll,{passive:true});window.addEventListener('resize',schedule);
 schedule();
 const before=root.querySelector('.v7-close').onclick;root.querySelector('.v7-close').onclick=()=>{closed=true;observer.disconnect();if(frame)cancelAnimationFrame(frame);feed.removeEventListener('wheel',wheel);feed.removeEventListener('keydown',key);feed.removeEventListener('pointerdown',pointer);feed.removeEventListener('scroll',scroll);window.removeEventListener('resize',schedule);if(oldPadding)feed.style.setProperty('padding-bottom',oldPadding,oldPriority);else feed.style.removeProperty('padding-bottom');before();};
})();

